import{_ as t,a0 as l,w as o,s as d,ao as r,I as p,x as a,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"更深入地了解 Linux 权限 | LCTT x X-CMD","titleTemplate":false,"description":"更深入地了解 Linux 权限 | LCTT (201906) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"更深入地了解 Linux 权限 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"更深入地了解 Linux 权限 | LCTT (201906) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201906/20190527 A deeper dive into Linux permissions","title":"更深入地了解 Linux 权限","tag":"201906","desc":""},"relativePath":"201906/20190527 A deeper dive into Linux permissions.md","filePath":"[post].md"}'),c={name:"201906/20190527 A deeper dive into Linux permissions.md"};function h(g,s,u,k,b,f){const n=l("Link");return o(),d("div",null,[s[15]||(s[15]=r(`<h1 id="更深入地了解-linux-权限" tabindex="-1">更深入地了解 Linux 权限 <a class="header-anchor" href="#更深入地了解-linux-权限" aria-label="Permalink to “更深入地了解 Linux 权限”">​</a></h1><blockquote><p>在 Linux 上查看文件权限时，有时你会看到的不仅仅是普通的 r、w、x 和 -。如何更清晰地了解这些字符试图告诉你什么以及这些权限如何工作？</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/201906/07/150718q09wnve6ne6v9063.jpg" alt="Sandra Henry-Stocker"></p><p>在 Linux 上查看文件权限时，有时你会看到的不仅仅是普通的 <code>r</code>、<code>w</code>、<code>x</code> 和 <code>-</code>。除了在所有者、组和其他中看到 <code>rwx</code> 之外，你可能会看到 <code>s</code> 或者 <code>t</code>，如下例所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>drwxrwsrwt</span></span></code></pre></div><p>要进一步明确的方法之一是使用 <code>stat</code> 命令查看权限。<code>stat</code> 的第四行输出以八进制和字符串格式显示文件权限：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ stat /var/mail</span></span>
<span class="line"><span>  File: /var/mail</span></span>
<span class="line"><span>  Size: 4096            Blocks: 8          IO Block: 4096   directory</span></span>
<span class="line"><span>Device: 801h/2049d      Inode: 1048833     Links: 2</span></span>
<span class="line"><span>Access: (3777/drwxrwsrwt)  Uid: (    0/    root)   Gid: (    8/    mail)</span></span>
<span class="line"><span>Access: 2019-05-21 19:23:15.769746004 -0400</span></span>
<span class="line"><span>Modify: 2019-05-21 19:03:48.226656344 -0400</span></span>
<span class="line"><span>Change: 2019-05-21 19:03:48.226656344 -0400</span></span>
<span class="line"><span> Birth: -</span></span></code></pre></div><p>这个输出提示我们，分配给文件权限的位数超过 9 位。事实上，有 12 位。这些额外的三位提供了一种分配超出通常的读、写和执行权限的方法 - 例如，<code>3777</code>（二进制 <code>011111111111</code>）表示使用了两个额外的设置。</p><p>该值的第一个 <code>1</code> （第二位）表示 SGID（设置 GID），为运行文件而赋予临时权限，或以该关联组的权限来使用目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>011111111111</span></span>
<span class="line"><span> ^</span></span></code></pre></div><p>SGID 将正在使用该文件的用户作为该组成员之一而分配临时权限。</p><p>第二个 <code>1</code>（第三位）是“粘连”位。它确保<em>只有</em>文件的所有者能够删除或重命名该文件或目录。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>011111111111</span></span>
<span class="line"><span>  ^</span></span></code></pre></div><p>如果权限是 <code>7777</code> 而不是 <code>3777</code>，我们知道 SUID（设置 UID）字段也已设置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>111111111111</span></span>
<span class="line"><span>^</span></span></code></pre></div><p>SUID 将正在使用该文件的用户作为文件拥有者分配临时权限。</p><p>至于我们上面看到的 <code>/var/mail</code> 目录，所有用户都需要访问，因此需要一些特殊值来提供它。</p><p>但现在让我们更进一步。</p><p>特殊权限位的一个常见用法是使用 <code>passwd</code> 之类的命令。如果查看 <code>/usr/bin/passwd</code> 文件，你会注意到 SUID 位已设置，它允许你更改密码（以及 <code>/etc/shadow</code> 文件的内容），即使你是以普通（非特权）用户身份运行，并且对此文件没有读取或写入权限。当然，<code>passwd</code> 命令很聪明，不允许你更改其他人的密码，除非你是以 root 身份运行或使用 <code>sudo</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l /usr/bin/passwd</span></span>
<span class="line"><span>-rwsr-xr-x 1 root root 63736 Mar 22 14:32 /usr/bin/passwd</span></span>
<span class="line"><span>$ ls -l /etc/shadow</span></span>
<span class="line"><span>-rw-r----- 1 root shadow 2195 Apr 22 10:46 /etc/shadow</span></span></code></pre></div><p>现在，让我们看一下使用这些特殊权限可以做些什么。</p><h3 id="如何分配特殊文件权限" tabindex="-1">如何分配特殊文件权限 <a class="header-anchor" href="#如何分配特殊文件权限" aria-label="Permalink to “如何分配特殊文件权限”">​</a></h3><p>与 Linux 命令行中的许多东西一样，你可以有不同的方法设置。 <code>chmod</code> 命令允许你以数字方式或使用字符表达式更改权限。</p><p>要以数字方式更改文件权限，你可以使用这样的命令来设置 SUID 和 SGID 位：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod 6775 tryme</span></span></code></pre></div><p>或者你可以使用这样的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ chmod ug+s tryme &lt;== 用于 SUID 和 SGID 权限</span></span></code></pre></div><p>如果你要添加特殊权限的文件是脚本，你可能会对它不符合你的期望感到惊讶。这是一个非常简单的例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat tryme</span></span>
<span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span></span></span>
<span class="line"><span>echo I am $USER</span></span></code></pre></div><p>即使设置了 SUID 和 SGID 位，并且 root 是文件所有者，运行脚本也不会产生你可能期望的 “I am root”。为什么？因为 Linux 会忽略脚本的 SUID 和 SGID 位。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ls -l tryme</span></span>
<span class="line"><span>-rwsrwsrwt 1 root root 29 May 26 12:22 tryme</span></span>
<span class="line"><span>$ ./tryme</span></span>
<span class="line"><span>I am jdoe</span></span></code></pre></div><p>另一方面，如果你对一个编译的程序之类进行类似的尝试，就像下面这个简单的 C 程序一样，你会看到不同的效果。在此示例程序中，我们提示用户输入文件名并创建它，并给文件写入权限。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    FILE *fp;   /* file pointer*/</span></span>
<span class="line"><span>    char fName[20];</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;Enter the name of file to be created: &quot;);</span></span>
<span class="line"><span>    scanf(&quot;%s&quot;,fName);</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    /* create the file with write permission */</span></span>
<span class="line"><span>    fp=fopen(fName,&quot;w&quot;);</span></span>
<span class="line"><span>    /* check if file was created */</span></span>
<span class="line"><span>    if(fp==NULL)</span></span>
<span class="line"><span>    {</span></span>
<span class="line"><span>        printf(&quot;File not created&quot;);</span></span>
<span class="line"><span>        exit(0);</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    printf(&quot;File created successfully\\n&quot;);</span></span>
<span class="line"><span>    return 0;</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>编译程序并运行该命令以使 root 用户成为所有者并设置所需权限后，你将看到它以预期的 root 权限运行 - 留下新创建的 root 为所有者的文件。当然，你必须具有 <code>sudo</code> 权限才能运行一些需要的命令。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cc -o mkfile mkfile.c            &lt;== 编译程序</span></span>
<span class="line"><span>$ sudo chown root:root mkfile       &lt;== 更改所有者和组为 “root”</span></span>
<span class="line"><span>$ sudo chmod ug+s mkfile        &lt;== 添加 SUID and SGID 权限</span></span>
<span class="line"><span>$ ./mkfile              &lt;== 运行程序</span></span>
<span class="line"><span>Enter name of file to be create: empty</span></span>
<span class="line"><span>File created successfully</span></span>
<span class="line"><span>$ ls -l empty</span></span>
<span class="line"><span>-rw-rw-r-- 1 root root 0 May 26 13:15 empty</span></span></code></pre></div><p>请注意，文件所有者是 root - 如果程序未以 root 权限运行，则不会发生这种情况。</p><p>权限字符串中不常见设置的位置（例如，rw<strong>s</strong>rw<strong>s</strong>rw<strong>t</strong>）可以帮助提醒我们每个位的含义。至少第一个 “s”（SUID） 位于所有者权限区域中，第二个 （SGID） 位于组权限区域中。为什么粘连位是 “t” 而不是 “s” 超出了我的理解。也许创造者想把它称为 “tacky bit”，但由于这个词的不太令人喜欢的第二个定义而改变了他们的想法。无论如何，额外的权限设置为 Linux 和其他 Unix 系统提供了许多额外的功能。</p><hr>`,38)),p("p",null,[s[1]||(s[1]=a("via: ",-1)),e(n,{href:"https://www.networkworld.com/article/3397790/a-deeper-dive-into-linux-permissions.html"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.networkworld.com/article/3397790/a-deeper-dive-into-linux-permissions.html",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=a("作者：",-1)),e(n,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:i(()=>[...s[2]||(s[2]=[a("Sandra Henry-Stocker",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),e(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[a("lujun9972",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),e(n,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),e(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("本文由 ",-1)),e(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),e(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const w=t(c,[["render",h]]);export{y as __pageData,w as default};
